-- section 1: Profitability Analysis
SELECT COUNTRIES, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY GROUP BY COUNTRIES ORDER BY TOTAL_PROFIT ASC LIMIT 5;
SELECT MIN(PROFIT) AS LOWEST_PROFIT FROM BREWERY WHERE MONTHS = 'December' AND YEARS = 2018;
SELECT COUNTRIES, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY GROUP BY COUNTRIES ORDER BY TOTAL_PROFIT DESC LIMIT 1;
SELECT YEARS, MAX(PROFIT) AS HIGHEST_SINGLE_PROFIT FROM BREWERY GROUP BY YEARS ORDER BY HIGHEST_SINGLE_PROFIT DESC LIMIT 1;
SELECT MONTHS, MIN(PROFIT) AS MIN_PROFIT FROM BREWERY GROUP BY MONTHS ORDER BY MIN_PROFIT DESC LIMIT 1;
SELECT BRANDS, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY WHERE COUNTRIES = 'Senegal' GROUP BY BRANDS ORDER BY TOTAL_PROFIT DESC LIMIT 1;
SELECT BRANDS, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY WHERE COUNTRIES IN ('Togo', 'Benin', 'Senegal') AND YEARS IN (2018, 2019)  GROUP BY BRANDS ORDER BY TOTAL_PROFIT DESC LIMIT 3;
SELECT BRANDS, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY WHERE COUNTRIES = 'Ghana' GROUP BY BRANDS ORDER BY TOTAL_PROFIT DESC LIMIT 2;
SELECT BRANDS, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY WHERE COUNTRIES IN ('Ghana', 'Nigeria')  GROUP BY BRANDS ORDER BY TOTAL_PROFIT DESC;
SELECT BRANDS, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY  WHERE COUNTRIES = 'Nigeria' AND YEARS = 2019 GROUP BY BRANDS  ORDER BY TOTAL_PROFIT DESC LIMIT 1;


-- Region and brand analysis 
SELECT DISTINCT BRANDS FROM BREWERY WHERE COUNTRIES = 'Nigeria' AND REGION = 'Southsouth';
SELECT REGION, SUM(QUANTITY) AS TOTAL_QUANTITY FROM BREWERY WHERE COUNTRIES = 'Nigeria' AND BRANDS = 'Budweiser' GROUP BY REGION;  
SELECT REGION, SUM(QUANTITY) AS TOTAL_QUANTITY FROM BREWERY WHERE COUNTRIES = 'Nigeria'  AND BRANDS = 'Budweiser' AND YEARS = 2019 GROUP BY REGION; 
SELECT REGION, SUM(QUANTITY) AS TOTAL_QUANTITY FROM BREWERY WHERE COUNTRIES = 'Nigeria'   AND BRANDS = 'Budweiser'   AND YEARS = 2019 GROUP BY REGION;
SELECT SALES_REP, MAX(PROFIT) AS MAX_PROFIT FROM BREWERY WHERE BRANDS = 'Budweiser' GROUP BY SALES_REP ORDER BY MAX_PROFIT DESC LIMIT 1; 
SELECT COUNTRIES, SUM(PROFIT) AS TOTAL_PROFIT FROM BREWERY WHERE YEARS = 2019    AND MONTHS IN ('October', 'November', 'December') GROUP BY COUNTRIES ORDER BY TOTAL_PROFIT DESC LIMIT 1;